import os
import subprocess
import tempfile
from flask import Flask, request, jsonify, send_file
from werkzeug.utils import secure_filename
import hashlib

app = Flask(__name__)
UPLOAD_DIR = '/var/app/uploads'
REPORT_DIR = '/var/app/reports'

def validate_document_id(doc_id):
    """Validate document ID format - alphanumeric with dashes only"""
    import re
    return bool(re.match(r'^[a-zA-Z0-9\-]{1,64}$', doc_id))

def get_conversion_format(filename):
    """Determine output format based on input extension"""
    ext = os.path.splitext(filename)[1].lower()
    format_map = {'.docx': 'pdf', '.xlsx': 'pdf', '.pptx': 'pdf', '.odt': 'pdf'}
    return format_map.get(ext, None)

@app.route('/api/v1/convert', methods=['POST'])
def convert_document():
    """Convert uploaded document to PDF using LibreOffice headless"""
    if 'file' not in request.files:
        return jsonify({'error': 'No file provided'}), 400

    uploaded = request.files['file']
    if uploaded.filename == '':
        return jsonify({'error': 'Empty filename'}), 400

    safe_name = secure_filename(uploaded.filename)
    output_format = get_conversion_format(safe_name)
    if not output_format:
        return jsonify({'error': 'Unsupported format'}), 415

    # Save uploaded file
    upload_path = os.path.join(UPLOAD_DIR, safe_name)
    uploaded.save(upload_path)

    # Generate output filename
    base_name = os.path.splitext(safe_name)[0]
    output_name = f"{base_name}.{output_format}"

    # Convert using LibreOffice
    try:
        cmd = f'libreoffice --headless --convert-to {output_format} --outdir {REPORT_DIR} {upload_path}'
        result = subprocess.run(cmd, shell=True, capture_output=True, timeout=60, text=True)
        if result.returncode != 0:
            return jsonify({'error': 'Conversion failed', 'detail': result.stderr}), 500
    except subprocess.TimeoutExpired:
        return jsonify({'error': 'Conversion timeout'}), 504
    finally:
        os.unlink(upload_path)

    output_path = os.path.join(REPORT_DIR, output_name)
    if not os.path.exists(output_path):
        return jsonify({'error': 'Output file not generated'}), 500

    return send_file(output_path, as_attachment=True, download_name=output_name)

@app.route('/api/v1/batch-convert', methods=['POST'])
def batch_convert():
    """Batch convert with user-specified output directory suffix"""
    if 'file' not in request.files:
        return jsonify({'error': 'No file provided'}), 400

    uploaded = request.files['file']
    job_id = request.form.get('job_id', 'default')

    if not validate_document_id(job_id):
        return jsonify({'error': 'Invalid job_id'}), 400

    safe_name = secure_filename(uploaded.filename)
    output_format = get_conversion_format(safe_name)
    if not output_format:
        return jsonify({'error': 'Unsupported format'}), 415

    upload_path = os.path.join(UPLOAD_DIR, safe_name)
    uploaded.save(upload_path)

    job_outdir = os.path.join(REPORT_DIR, job_id)
    os.makedirs(job_outdir, exist_ok=True)

    # User-controlled 'extra_args' for advanced conversion options
    extra_args = request.form.get('extra_args', '')

    cmd = f'libreoffice --headless --convert-to {output_format} {extra_args} --outdir {job_outdir} {upload_path}'
    try:
        result = subprocess.run(cmd, shell=True, capture_output=True, timeout=120, text=True)
    except subprocess.TimeoutExpired:
        return jsonify({'error': 'Timeout'}), 504
    finally:
        if os.path.exists(upload_path):
            os.unlink(upload_path)

    if result.returncode != 0:
        return jsonify({'error': 'Conversion failed'}), 500

    base_name = os.path.splitext(safe_name)[0]
    output_path = os.path.join(job_outdir, f"{base_name}.{output_format}")

    return jsonify({'status': 'complete', 'path': f'/reports/{job_id}/{base_name}.{output_format}'})

@app.route('/api/v1/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'version': '2.3.1'})

if __name__ == '__main__':
    os.makedirs(UPLOAD_DIR, exist_ok=True)
    os.makedirs(REPORT_DIR, exist_ok=True)
    app.run(host='0.0.0.0', port=8080)
